        new Error('Oops'),
      );
    })

it('should allow providing a factory function to mapStateToProps', () => {
      let updateCount = 0;
      let memoizedReturnCount = 0;
      const store = createStore(() => ({ value: 1 }));

      const mapStateFactory = () => {
        let lastProp;
        let lastVal;
        let lastResult;
        return (state, props) => {
          if (props.name === lastProp && lastVal === state.value) {
            memoizedReturnCount++;
            return lastResult;
          }

          lastProp = props.name;
          lastVal = state.value;
          lastResult = {
            someObject: { prop: props.name, stateVal: state.value },
          };
          return lastResult;
        };
      };

      const Container = connect(mapStateFactory)(
        class Container extends Component {
          componentWillUpdate() {
            updateCount++;
          }

          render() {
            return <Passthrough {...this.props} />;
          }
        },
      );

      renderToContainer(
        <ProviderMock store={store}>
          <div>
            <Container name="a" />
            <Container name="b" />
          </div>
        </ProviderMock>,
      );

      store.dispatch({ type: 'test' });
      expect(updateCount).toBe(0);
      expect(memoizedReturnCount).toBe(2);
    })

it('should allow providing a factory function to mapDispatchToProps', (done) => {
      let updatedCount = 0;
      let memoizedReturnCount = 0;
      const store = createStore(() => ({ value: 1 }));

      const mapDispatchFactory = () => {
        let lastProp;
        let lastResult;
        return (dispatch, props) => {
          if (props.name === lastProp) {
            memoizedReturnCount++;
            return lastResult;
          }

          lastProp = props.name;
          lastResult = { someObject: { dispatchFn: dispatch } };
          return lastResult;
        };
      };

      const mergeParentDispatch = (stateProps, dispatchProps, parentProps) => ({
        ...stateProps,
        ...dispatchProps,
        name: parentProps.name,
      });

      const Passthrough = connect(
        null,
        mapDispatchFactory,
        mergeParentDispatch,
      )(
        class Passthrough extends Component {
          componentWillUpdate() {
            updatedCount++;
          }

          render() {
            return <div />;
          }
        },
      );

      class Container extends Component {
        constructor(props) {
          super(props);
          this.state = { count: 0 };
        }

        componentDidMount() {
          this.setState({ count: 1 });
        }

        render() {
          const { count } = this.state;
          return (
            <div>
              <Passthrough count={count} name="a" />
              <Passthrough count={count} name="b" />
            </div>
          );
        }
      }
      const vNode = (
        <ProviderMock store={store}>
          <Container />
        </ProviderMock>
      );
      renderToContainer(vNode);

      setTimeout(() => {
        store.dispatch({ type: 'test' });
        renderToContainer(vNode);
        expect(updatedCount).toBe(0);
        expect(memoizedReturnCount).toBe(2);
        done();
      }, 20);
    })

