      expect(renderCalls).toBe(1);

      store.dispatch({ type: 'APPEND', payload: 'a' });
      renderToContainer(vNode);

      expect(mapStateCalls).toBe(2);
      expect(renderCalls).toBe(1);
    });

    it('should update impure components with custom mergeProps', (done) => {
      const store = createStore(() => ({}));
