    it('should allow to clean up child state in parent componentWillUnmount', () => {
      const reducer = (state = { data: null }, action) => {
        switch (action.type) {
          case 'fetch':
            return { data: { profile: { name: 'April' } } };
          case 'clean':
            return { data: null };
          default:
            return state;
