          render() {
            return <Child />;
          }
        },
      );

      const store = createStore(reducer);
      const div = document.createElement('div');
      render(
        <ProviderMock store={store}>
          <Parent />
        </ProviderMock>,
        div,
      );

      unmountDOM(div);
      expect(store.getState().data).toEqual(null);
    });

