    it('should not attempt to set state after unmounting nested components', () => {
      const store = createStore(() => ({}));
      let mapStateToPropsCalls = 0;

      let linkA;
      let linkB;

      let App = ({ children, setLocation }) => {
        const onClick = (to) => (event) => {
          event.preventDefault();
          setLocation(to);
        };

        return (
          <div>
            <a
              href="#"
              onClick={onClick('a')}
              ref={(c) => {
                linkA = c;
              }}
            >
              A
            </a>
            <a
              href="#"
              onClick={onClick('b')}
              ref={(c) => {
                linkB = c;
              }}
            >
              B
            </a>
            {children}
          </div>
        );
      };
      App = connect(() => ({}))(App);

      let A = () => <h1>A</h1>;
      A = connect(() => ({ calls: ++mapStateToPropsCalls }))(A);

      const B = () => <h1>B</h1>;

      class RouterMock extends Component {
        constructor(...args) {
          super(...args);
          this.state = { location: { pathname: 'a' } };
          this.setLocation = this.setLocation.bind(this);
        }

        setLocation(pathname) {
          store.dispatch({ type: 'TEST' });
          this.setState({ location: { pathname } });
        }

        getChildComponent(location) {
          switch (location) {
            case 'a':
              return <A />;
            case 'b':
              return <B />;
            default:
              throw new Error('Unknown location: ' + location);
          }
        }

        render() {
          return (
            <App setLocation={this.setLocation}>
              {this.getChildComponent(this.state.location.pathname)}
            </App>
          );
        }
      }

      let wrapper;
      const div = document.createElement('div');
      document.body.appendChild(div);
      const vNode = (
        <Wrapper
          ref={(w) => {
            wrapper = w;
          }}
        >
          <ProviderMock store={store}>
            <RouterMock />
          </ProviderMock>
        </Wrapper>
      );
      render(vNode, div);

      const spy = spyOn(console, 'error');
      expect(mapStateToPropsCalls).toBe(1);
      linkA.click();
      render(vNode, div);
      expect(mapStateToPropsCalls).toBe(2);
      linkB.click();
      render(vNode, div);

      expect(mapStateToPropsCalls).toBe(3);
      linkB.click();
      render(vNode, div);

      expect(spy.calls.count()).toBe(0);

      unmountDOM(div);
      document.body.removeChild(div);
      expect(mapStateToPropsCalls).toBe(3);
    });

