    expect(emitter.listeners[0]).toEqual(listener1);

    listener();
    listener();
    listener();

    expect(emitter.listeners.length).toEqual(1);

    emitter.emit('foobar');

    expect(console.error.calls.count()).toBe(1);
    expect(console.error.calls.argsFor(0)[0]).toContain('foobar');
  })

