it('should unset a namespaced attributes #2', () => {
    const template = (val) =>
      createElement('image', {
        'xlink:href': val,
      });

    render(template(null), container);
    expect(
      container.firstChild.hasAttributeNS(
        'http://www.w3.org/1999/xlink',
        'href',
      ),
    ).toBe(false);

    render(template(null), container);
    expect(
      container.firstChild.hasAttributeNS(
        'http://www.w3.org/1999/xlink',
        'href',
      ),
    ).toBe(false);
  })

