it('"onComponentDidAppear" hook should fire, args dom props', () => {
      const spyObj = {
        fn: () => {},
      };

      const spy = spyOn(spyObj, 'fn');
      const t = animationTemplate(spyObj.fn, null, StatelessComponent);

      const node1 = t({ a: 1 });
      render(node1, container);
