    calledSecondTest = false;

    render(null, container);
    divs = container.querySelectorAll('div');
    for (const div of divs) {
      div.click();
    }

    expect(calledFirstTest).toBe(false);
    expect(calledSecondTest).toBe(false);
    done();
  })

