it('Should work with spread attributes', (done) => {
    function SmallComponent(props) {
      return (
        <div id="testClick" {...props}>
          FooBar
        </div>
      );
    }

    const obj = {
      test: function () {
        done();
      },
    };

    render(
      <SmallComponent className="testing" onClick={obj.test} />,
      container,
    );

    container.querySelector('#testClick').click();
  })
